def potencia(base, exp):
    resultado = 1
    for _ in range(exp):
        resultado *= base
    return resultado

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def duplicar_lista(lst):
    result = []
    for item in lst:
        result.append(item * 2)
    return result

def longitud(texto):
    contador = 0
    for c in texto:
        contador += 1
    return contador

def maximo(a, b):
    if a > b:
        return a
    else:
        return b
